const resolvePushIcon = (input) => {
  if (!input) {
    return '';
  }
  if (typeof input === 'string') {
    const trimmed = input.trim();
    if (trimmed === '') {
      return '';
    }
    if (trimmed.startsWith('data:image')) {
      return trimmed;
    }
    return GO_PUSH_ICON_MAP[trimmed] || '';
  }
  return '';
};

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  if (!event.data) {
    return;
  }

  const payload = event.data.json ? event.data.json() : {};
  const title = payload.title || 'Notificación';
  const iconValue = resolvePushIcon(payload.icon || payload.badge || payload.icon_slug) || GO_PUSH_ICON_MAP.notify_logo || '';
  const badgeValue = resolvePushIcon(payload.badge || payload.icon || payload.icon_slug) || iconValue;
  const options = {
    body: payload.body || '',
    icon: iconValue,
    badge: badgeValue,
    data: {
      url: payload.link || '',
      notificationId: payload.id || 0,
    },
    actions: Array.isArray(payload.actions)
      ? payload.actions.map((action) => ({
          action: action.action || 'open',
          title: action.title || '',
        }))
      : [],
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data && event.notification.data.url;
  if (!targetUrl) {
    return;
  }

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      const client = clients.find((c) => c.url === targetUrl);
      if (client) {
        return client.focus();
      }
      return self.clients.openWindow(targetUrl);
    })
  );
});

self.addEventListener('notificationclose', (event) => {
  // Placeholder for analytics or synchronization.
});
